#!/usr/bin/env python3
"""Reproduce the bibliography and supporting indices for slice A.

Run after author_data.py. Bibliography metadata and verification details are
documented in research_notes.md; raw retrievals remain in evidence/*.json.
"""
from pathlib import Path
import csv, json, re

OUT=Path(__file__).resolve().parents[1]
ROOT=OUT.parents[1]
items=json.loads((OUT/'items.json').read_text())
needed={k for x in items for k in x['refs']}

def bib_blocks(text):
    for m in re.finditer(r'@\w+\s*\{\s*([^,]+),',text):
        start=m.start(); depth=1; pos=m.end()
        while depth and pos<len(text):
            c=text[pos]
            if c=='{' and (pos==0 or text[pos-1]!='\\'): depth+=1
            if c=='}' and (pos==0 or text[pos-1]!='\\'): depth-=1
            pos+=1
        yield m.group(1).strip(),text[start:pos]

bib={}
for k,v in bib_blocks((ROOT/'work/references_cumulative.bib').read_text()):
    if k in needed and k not in bib: bib[k]=v

def add(key,typ='article',**fields):
    if key in bib: return
    fields.setdefault('note','verified')
    bib[key]='@'+typ+'{'+key+',\n'+',\n'.join('  '+k+' = {'+str(v)+'}' for k,v in fields.items())+'\n}'

